draw(A--B--C--cycle);
draw(A--T);
draw(D--E);

label("$A$", A, N);
label("$B$", B, SW);
label("$C$", C, SE);
label("$D$", D, W);
label("$E$", E, NE);
label("$F$", F, SW);
label("$T$", T, S);
[/asy]

